package com.idfc.ai.runbook.api; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,NoSuchElementException.class}) ResponseEntity<Map<String,String>> error(Exception e){String code=e.getMessage()!=null&&e.getMessage().startsWith("RUNBOOK_")?e.getMessage().split("[: ]")[0]:"RUNBOOK_REQUEST_INVALID";HttpStatus s=code.equals("RUNBOOK_JOB_NOT_FOUND")?HttpStatus.NOT_FOUND:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("code",code,"message","Runbook request could not be completed"));} }
